// Bounded, actual staged search UI. No submissions or external navigation.
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {mkdir,mkdtemp,readFile,writeFile,symlink} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join,resolve} from 'node:path';
import {staticOrigin} from './static-origin.mjs';
import {inventory} from '../../scripts/build-pages-artifact.mjs';
assert.equal(process.env.GITHUB_ACTIONS,'true','Only the authorized Linux Actions browser');
const mode=process.env.SEARCH_MODE;assert(['baseline','current'].includes(mode));
const require=createRequire(import.meta.url),{chromium}=require(process.env.PLAYWRIGHT_PACKAGE);
const git=(...a)=>execFileSync('git',a),sha=b=>createHash('sha256').update(b).digest('hex');
const artifact=resolve(process.env.PAGES_ARTIFACT),reportDir=resolve(process.env.BROWSER_REPORT);await mkdir(reportDir,{recursive:true});
const labels={uk:{native:'Українська',empty:'Мову не знайдено.'},ru:{native:'Русский',empty:'Язык не найден.'},tr:{native:'Türkçe',empty:'Dil bulunamadı.'},tg:{native:'Тоҷикӣ',empty:'Забон ёфт нашуд.'},vi:{native:'Tiếng Việt',empty:'Không tìm thấy ngôn ngữ.'}};
const report={mode,head:process.env.TESTED_HEAD,base:process.env.TESTED_BASE,checkout:git('rev-parse','HEAD').toString().trim(),files:{},rows:[],captures:[],external:[],mutations:[],limits:['Actual unmodified staged app in Chromium320/1280. Unicode input uses Playwright keyboard.insertText and input events; physical/mobile/IME composition, native speaker and screen reader certification are not claimed.','Baseline observes a missing match for five canonically equivalent NFD labels, then recovers with the same NFC label. Current mode requires both representations to match. No accent stripping or translation changes are assumed.','Only search-area components are captured. Recruiter/form entry is asserted in DOM; no new whole-page or offline certificate. No actual candidate answers, messages, accounts or submissions.']};
if(mode==='baseline'){
 assert.equal(report.checkout,report.head);assert.equal(git('show','-s','--format=%P','HEAD').toString().trim(),report.base);
 const old=git('ls-tree','-r',report.base).toString().trim().split('\n');assert.equal(old.length,514);
 for(const row of old){const [,path]=row.split('\t');if(path==='docs/primserv-roadmap.md')continue;assert.deepEqual(git('show',report.head+':'+path),git('show',report.base+':'+path),path);}report.priorTrackedUnchanged=513;
}else{assert.deepEqual(git('show','-s','--format=%P','HEAD').toString().trim().split(' '),[report.base,report.head]);assert.equal(git('rev-parse','HEAD^{tree}').toString().trim(),git('rev-parse',report.head+'^{tree}').toString().trim());}
for(const {path:p}of inventory(artifact)){const source=p.startsWith('tools/coordinator/')?'coordinator-demo/'+p.split('/').at(-1):p,b=await readFile(join(artifact,p));assert.deepEqual(b,git('show',report.head+':'+source));report.files[p]={source,bytes:b.length,sha256:sha(b),publishedExact:b.equals(git('show',report.base+':'+source))};}assert.equal(Object.keys(report.files).length,317);if(mode==='baseline')assert.equal(Object.values(report.files).filter(x=>x.publishedExact).length,316);
const serveRoot=await mkdtemp(join(tmpdir(),'primserv-language-search-'));await symlink(artifact,join(serveRoot,'kiris-jobs'),'dir');const origin=staticOrigin(serveRoot),base='http://127.0.0.1:4173/kiris-jobs/';let browser;
async function input(page,value){const field=page.locator('#languageSearch');await field.focus();await page.keyboard.press('Control+A');await page.keyboard.press('Backspace');await page.keyboard.insertText(value);assert.equal(await field.inputValue(),value);assert.equal(await page.evaluate(()=>document.activeElement.id),'languageSearch');assert(await field.evaluate(n=>n===window.__originalSearch));}
async function capture(page,width,lang,stage){
 await page.evaluate(()=>document.fonts.ready);await page.locator('#languageSearch').scrollIntoViewIfNeeded();await page.waitForTimeout(100);
 const dom=await page.evaluate(()=>{const field=document.getElementById('languageSearch'),grid=document.querySelector('.language-grid'),f=field.getBoundingClientRect(),g=grid.getBoundingClientRect(),text=[...grid.querySelectorAll('strong,small,p,span.language-code')].map(n=>({text:n.textContent,visible:n.checkVisibility(),fit:n.scrollWidth<=n.clientWidth+1}));return{query:field.value,focused:document.activeElement===field,inputNodeKept:field===window.__originalSearch,visible:field.checkVisibility()&&grid.checkVisibility(),lang:document.documentElement.lang,cards:[...grid.querySelectorAll('[data-language]')].map(n=>n.dataset.language),empty:grid.querySelector('[role="status"]')?.textContent||'',fit:document.documentElement.scrollWidth<=innerWidth+1&&f.left>=0&&f.right<=innerWidth&&g.left>=0&&g.right<=innerWidth&&text.every(t=>t.visible&&t.fit),text,clip:{x:Math.max(0,f.left-4),y:Math.max(0,f.top-4),width:Math.min(innerWidth,f.right+4)-Math.max(0,f.left-4),height:g.bottom-Math.max(0,f.top-4)+4}};});
 assert(dom.visible&&dom.focused&&dom.inputNodeKept&&dom.fit&&dom.lang===lang);const file=`search-${width}-${lang}-${stage}.png`;await page.screenshot({path:join(reportDir,file),clip:dom.clip});const b=await readFile(join(reportDir,file));report.captures.push({file,width,lang,stage,sha256:sha(b),dom,originalPixels:true});
}
async function run(width,lang,index){
 const ctx=await browser.newContext({viewport:{width,height:1000},serviceWorkers:'block',reducedMotion:'reduce'});ctx.setDefaultTimeout(15000);
 await ctx.route('**/*',route=>{const r=route.request(),u=new URL(r.url());if(!['GET','HEAD'].includes(r.method())){report.mutations.push({lang,width,method:r.method(),path:u.pathname,blocked:true});return route.abort();}if(u.origin!==new URL(base).origin){report.external.push({lang,width,host:u.hostname,path:u.pathname,blocked:true});return route.abort();}return route.continue();});
 const page=await ctx.newPage(),errors=[];page.on('pageerror',e=>errors.push(e.message));
 try{
  await page.goto(base+'apply/?lang='+lang);assert.equal(await page.locator('html').getAttribute('lang'),lang);const native=labels[lang].native,nfd=native.normalize('NFD');assert.notEqual(native,nfd);assert.equal(await page.evaluate(lang=>window.CITRONEX_SIMPLE_I18N.languages[lang].native,lang),native);await page.evaluate(()=>window.__originalSearch=document.getElementById('languageSearch'));
  await input(page,nfd);const nfdCards=await page.locator('.language-grid [data-language]').evaluateAll(nodes=>nodes.map(n=>n.dataset.language));
  if(mode==='baseline'){assert.deepEqual(nfdCards,[]);assert.equal(await page.locator('.language-grid [role="status"]').innerText(),labels[lang].empty);}else{assert.deepEqual(nfdCards,[lang]);assert.equal(await page.locator('.language-grid [role="status"]').count(),0);}await capture(page,width,lang,'nfd');
  await input(page,native);assert.deepEqual(await page.locator('.language-grid [data-language]').evaluateAll(nodes=>nodes.map(n=>n.dataset.language)),[lang]);assert.equal(await page.locator('.language-grid [role="status"]').count(),0);await capture(page,width,lang,'native');
  await input(page,'');assert.equal(await page.locator('.language-grid [data-language]').count(),9);assert(await page.locator('[data-action="toggle-languages"]').isVisible());
  // The next Tab activates the single native-name result with the real Enter key.
  await input(page,mode==='current'?nfd:native);await page.keyboard.press('Tab');assert.equal(await page.evaluate(()=>document.activeElement.dataset.language),lang);await page.keyboard.press('Enter');assert.equal(await page.locator('.recruiter-card').count(),6);assert.equal(await page.locator('html').getAttribute('lang'),lang);
  const recruiter=await page.locator('.recruiter-card').nth(index%6).getAttribute('data-recruiter');await page.locator(`[data-recruiter="${recruiter}"]`).focus();await page.keyboard.press('Enter');assert.equal(await page.locator('#firstName').inputValue(),'');assert.equal(await page.locator('#phone').inputValue(),'');assert.equal(await page.locator('#candidateForm').count(),1);assert.equal(await page.locator('[data-action="send"]').count(),0);assert.equal(await page.locator('.form-link').evaluate(n=>n.open),false);assert.deepEqual(errors,[]);
  report.rows.push({lang,width,status:'passed',native,nfd,nfdMissingObserved:mode==='baseline',nfdMatched:mode==='current',nfcPositiveControl:true,sameSearchDOMAndFocus:true,clearingRestoresPriority:true,nativeTabEnterLanguage:true,nativeEnterRecruiter:true,sixRecruiterCards:true,blankFormRendered:true,noDelivery:true});
 }catch(e){report.failedCase??={lang,width,failure:e.message,errors};await page.screenshot({path:join(reportDir,`failure-search-${width}-${lang}.png`)}).catch(()=>{});throw e;}finally{await ctx.close();}
}
try{await origin.start();browser=await chromium.launch({headless:true});report.browser=browser.version();const matrix=[320,1280].flatMap(width=>Object.keys(labels).map((lang,index)=>({width,lang,index})));let next=0;await Promise.all(Array.from({length:2},async()=>{while(next<matrix.length){const r=matrix[next++];await run(r.width,r.lang,r.index);}}));assert.equal(report.rows.length,10);assert.equal(report.captures.length,20);assert.deepEqual(report.external,[]);assert.deepEqual(report.mutations,[]);report.applicationDeliveryAttempts=0;report.status=mode==='baseline'?'OBSERVED_10_NFD_NATIVE_SEARCH_MISSES_WITH_NFC_RECOVERY':'PASSED_10_CANONICALLY_EQUIVALENT_NATIVE_SEARCH_FLOWS';}catch(e){report.status='FAILED';report.failure=e.stack;throw e;}finally{await browser?.close();await origin.stop();await writeFile(join(reportDir,'acceptance.json'),JSON.stringify(report,null,2)+'\n');}
